 "content": "from collections import Counter


def _periodic_modal_lines(lines):
    """Find regularly spaced separator lines from their modal colors."""
    modes = [Counter(line).most_common(1)[0][0] for line in lines]
    candidates = []
    for color in set(modes):
        positions = [i for i, value in enumerate(modes) if value == color]
        if len(positions) >= 3:
            gaps = [b - a for a, b in zip(positions, positions[1:])]
            if len(set(gaps)) == 1:
                candidates.append((len(positions), color, positions))
    if not candidates:
        return None, []
    _, color, positions = max(candidates)
    return color, positions


def transform(grid):
    """Decode unanimous 2x2 junctions in a regularly spaced rail lattice."""
    h, w = len(grid), len(grid[0]) if grid else 0
    if not h or not w:
        return []

    rail_color, cols = _periodic_modal_lines(
        [[grid[r][c] for r in range(h)] for c in range(w)])
    row_color, rows = _periodic_modal_lines(grid)
    if rail_color is None or row_color is None or rail_color != row_color:
        return [row[:] for row in grid]

    background = Counter(v for row in grid for v in row
                         if v != rail_color).most_common(1)[0][0]
    out = []
    for i in range(len(rows) - 1):
        result_row = []
        for j in range(len(cols) - 1):
            corners = (grid[rows[i]][cols[j]], grid[rows[i]][cols[j + 1]],
                       grid[rows[i + 1]][cols[j]], grid[rows[i + 1]][cols[j + 1]])
            color = corners[0]
            result_row.append(color if color != rail_color and all(v == color for v in corners)
                              else background)
        out.append(result_row)

    # The demos show a compact crop around non-background decoded cells.
    while out and all(v == background for v in out[-1]):
        out.pop()
    while out and all(v == background for v in out[0]):
        out.pop(0)
    while out and all(v == background for v in out[-1]):
        out.pop()
    while out and all(row[-1] == background for row in out):
        for row in out:
            row.pop()
    while out and all(row[0] == background for row in out):
        for row in out:
            row.pop(0)
    return out


